import CryptoKit
import Foundation
import Testing
import VaultCore
@testable import SharingKit

/// The pinned chat vectors in Fixtures/chat_kat.json (generated by kat/crosscheck.py
/// `--write-chat` and checked against kat/NearbyProtocolReference.swift).
struct ChatKAT: Decodable {
    struct Inputs: Decodable {
        let skI: String
        let skR: String
        let nI: String
        let nR: String
        let nameI: String
        let nameR: String
        let labelPrefix: String
        let text_utf8: String
    }

    let inputs: Inputs
    let outputs: [String: String]

    static func load() throws -> ChatKAT {
        try JSONDecoder().decode(ChatKAT.self, from: Fixtures.data("chat_kat.json"))
    }

    func output(_ key: String) throws -> String {
        try #require(outputs[key])
    }

    func bytes(_ hex: String) throws -> Data {
        try #require(Data(hex: hex))
    }

    func keyMaterial(_ role: NearbyRole) throws -> NearbyKeyMaterial {
        let secret = try bytes(role == .initiator ? inputs.skI : inputs.skR)
        let nonce = try bytes(role == .initiator ? inputs.nI : inputs.nR)
        let key = try Curve25519.KeyAgreement.PrivateKey(rawRepresentation: secret)
        return NearbyKeyMaterial(privateKey: key, nonce: nonce)
    }
}

/// Drives two ``NearbyChatMachine``s by passing frames directly (no transport), recording every
/// frame and event. The intercept closures can rewrite, drop or duplicate frames.
struct ChatHarness {
    static let date = Date(timeIntervalSince1970: 1_790_000_000)

    var initiator: NearbyChatMachine
    var responder: NearbyChatMachine
    var initiatorEvents: [NearbyChatEvent] = []
    var responderEvents: [NearbyChatEvent] = []
    var initiatorFrames: [Data] = []
    var responderFrames: [Data] = []
    /// Payload requests each side's session would serve.
    var initiatorRequests: [ChatAttachmentID] = []
    var responderRequests: [ChatAttachmentID] = []
    var interceptToResponder: (Data) -> [Data] = { [$0] }
    var interceptToInitiator: (Data) -> [Data] = { [$0] }
    private var toResponder: [Data] = []
    private var toInitiator: [Data] = []

    init(initiator: NearbyChatMachine, responder: NearbyChatMachine) {
        self.initiator = initiator
        self.responder = responder
    }

    /// The KAT parties: fixed keys and nonces, names "Alice's Mac" / "Bob's Mac", chat version
    /// 1 on both sides (chat_kat.json was recorded with v1; a 0.2.x or 0.3.x Mac still offers
    /// it). `maxVersions` overrides the versions (v0.4.0 tests of configuration attachments).
    static func kat(maxVersions: (initiator: UInt8, responder: UInt8) = (1, 1)) throws -> ChatHarness {
        let kat = try ChatKAT.load()
        return ChatHarness(
            initiator: NearbyChatMachine(
                role: .initiator,
                localName: kat.inputs.nameI,
                keyMaterial: try kat.keyMaterial(.initiator),
                maxVersion: maxVersions.initiator
            ),
            responder: NearbyChatMachine(
                role: .responder,
                localName: kat.inputs.nameR,
                keyMaterial: try kat.keyMaterial(.responder),
                maxVersion: maxVersions.responder
            )
        )
    }

    mutating func recordInitiator(_ step: NearbyChatStep) {
        initiatorEvents += step.events
        initiatorFrames += step.frames
        initiatorRequests += step.payloadRequests
        for frame in step.frames {
            toResponder += interceptToResponder(frame)
        }
    }

    mutating func recordResponder(_ step: NearbyChatStep) {
        responderEvents += step.events
        responderFrames += step.frames
        responderRequests += step.payloadRequests
        for frame in step.frames {
            toInitiator += interceptToInitiator(frame)
        }
    }

    /// Delivers queued frames until both directions are empty.
    mutating func pump() {
        while !toResponder.isEmpty || !toInitiator.isEmpty {
            if !toResponder.isEmpty {
                let frame = toResponder.removeFirst()
                recordResponder(responder.receive(frame, at: Self.date))
            }
            if !toInitiator.isEmpty {
                let frame = toInitiator.removeFirst()
                recordInitiator(initiator.receive(frame, at: Self.date))
            }
        }
    }

    mutating func inject(toResponder frame: Data) {
        recordResponder(responder.receive(frame, at: Self.date))
        pump()
    }

    mutating func inject(toInitiator frame: Data) {
        recordInitiator(initiator.receive(frame, at: Self.date))
        pump()
    }

    /// Both started and connected; HELLO/HELLO/REVEAL done.
    mutating func runHandshake() throws {
        recordResponder(try responder.start())
        recordInitiator(try initiator.start())
        recordResponder(responder.transportConnected())
        recordInitiator(initiator.transportConnected())
        pump()
    }

    /// Handshake plus both confirmations: both sides are chatting.
    mutating func runToChatting() throws {
        try runHandshake()
        recordInitiator(try initiator.confirmSAS())
        recordResponder(try responder.confirmSAS())
        pump()
    }

    @discardableResult
    mutating func sendFromInitiator(_ text: String) throws -> ChatMessageModel? {
        let (step, message) = try initiator.sendText(text, at: Self.date)
        recordInitiator(step)
        pump()
        return message
    }

    @discardableResult
    mutating func sendFromResponder(_ text: String) throws -> ChatMessageModel? {
        let (step, message) = try responder.sendText(text, at: Self.date)
        recordResponder(step)
        pump()
        return message
    }

    /// The initiator's next encrypted sequence number (HELLO_I also starts with 0x01 but its
    /// second byte is the version, below every encrypted type).
    var nextInitiatorSequence: UInt64 {
        UInt64(initiatorFrames.filter { ($0.encryptedType ?? 0) >= NearbyChatMessageType.confirm.rawValue }.count)
    }

    var nextResponderSequence: UInt64 {
        UInt64(responderFrames.filter { ($0.encryptedType ?? 0) >= NearbyChatMessageType.confirm.rawValue }.count)
    }

    var initiatorAbort: NearbyAbortModel? {
        initiatorEvents.compactMap(\.abortModel).first
    }

    var responderAbort: NearbyAbortModel? {
        responderEvents.compactMap(\.abortModel).first
    }

    var responderMessages: [ChatMessageModel] {
        responderEvents.compactMap(\.messageModel)
    }

    var initiatorMessages: [ChatMessageModel] {
        initiatorEvents.compactMap(\.messageModel)
    }
}

/// Seals frames with the chat KAT direction keys, to forge protocol violations.
struct ChatKATForger {
    let initiatorToResponder: SymmetricKey
    let responderToInitiator: SymmetricKey

    init() throws {
        let kat = try ChatKAT.load()
        initiatorToResponder = SymmetricKey(data: try kat.bytes(try kat.output("k_i2r")))
        responderToInitiator = SymmetricKey(data: try kat.bytes(try kat.output("k_r2i")))
    }

    func fromInitiator(_ type: NearbyChatMessageType, sequence: UInt64, body: Data) throws -> Data {
        try NearbyEncryptedFrame.seal(rawType: type.rawValue, sequence: sequence, body: body, key: initiatorToResponder)
    }

    func fromResponder(_ type: NearbyChatMessageType, sequence: UInt64, body: Data) throws -> Data {
        try NearbyEncryptedFrame.seal(rawType: type.rawValue, sequence: sequence, body: body, key: responderToInitiator)
    }
}

/// Single-item packages for attachments.
enum ChatAttachmentFactory {
    /// A repository-level secret (scope `secret`) with `value`.
    static func secret(_ name: String = "API_KEY", value: String = "s3cr3t-value") -> SharePackageModel {
        PackageFactory.package(scope: .secret, secrets: [PackageFactory.item(name, value: value)])
    }

    /// An environment-level variable (scope `secret`) with `value`.
    static func environmentVariable(_ name: String = "LOG_LEVEL", value: String = "debug") -> SharePackageModel {
        PackageFactory.package(
            scope: .secret,
            environments: [PackageFactory.environment("staging", variables: [PackageFactory.item(name, value: value)])]
        )
    }
}

extension NearbyChatEvent {
    var abortModel: NearbyAbortModel? {
        if case .aborted(let model) = self { return model }
        return nil
    }

    var sasModel: NearbySASModel? {
        if case .sasReady(let model) = self { return model }
        return nil
    }

    var messageModel: ChatMessageModel? {
        if case .message(let model) = self { return model }
        return nil
    }

    var offerModel: ChatAttachmentOfferModel? {
        if case .attachmentOffered(let model) = self { return model }
        return nil
    }

    var receivedAttachment: (ChatAttachmentID, SharePackageModel)? {
        if case .attachmentReceived(let id, let package) = self { return (id, package) }
        return nil
    }

    var isTerminal: Bool {
        switch self {
        case .aborted, .peerClosed: true
        default: false
        }
    }
}

extension NearbyChatStep {
    var abortReason: NearbyAbortReason? {
        events.compactMap(\.abortModel).first?.reason
    }
}

extension Data {
    /// The type byte of an encrypted frame (`[ver][type][seq]...`), or nil for a plaintext frame.
    var encryptedType: UInt8? {
        count > NearbyProtocol.encryptedHeaderBytes && first == NearbyProtocol.maxVersion ? self[startIndex + 1] : nil
    }
}
